contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        // Ensure the test contract has a positive balance inside c so refund has an effect.
        c.deposit{value: depositAmount}();

        // Optionally withdraw some amount, leaving possibly zero balance.
        if (withdrawAmount > 0) {
            try c.withdraw(withdrawAmount) {
                // withdrawal succeeded
            } catch {}
        }

        // Record the cash-on-hand and the contract's Ether balance just before the deciding refund.
        uint256 cashBefore = address(this).balance;
        uint256 cBalBefore = address(c).balance;

        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // General rule: after a non-reverting refund, the contract's Ether balance
        // decreases by exactly the amount received by the test contract, and that
        // amount equals the caller's balance in c at the moment of the refund.
        if (!refundReverted) {
            uint256 received = address(this).balance - cashBefore;
            assert(cBalBefore - address(c).balance == received);
        } else {
            assert(address(c).balance == cBalBefore);
        }
    }

    receive() external payable {}
}

