        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 finalContractBalance = address(c).balance;
        uint256 finalTestBalance = address(this).balance;

        assert(
            (refundReverted == false && finalTestBalance >= preDepositTestBalance && finalContractBalance == preDepositContractBalance) ||
            (refundReverted == true && finalContractBalance == preDepositContractBalance + depositAmount)
        );
    }

    receive() external payable {}
}

